/**The component expects rich text, but we want to be able to simply edit a string and have that work */
const stringToSimpleRichText = (text: string) => ({
  raw: JSON.stringify({
    nodeType: "document",
    data: {},
    content: [
      {
        nodeType: "paragraph",
        data: {},
        content: [
          {
            nodeType: "text",
            value: text,
            marks: [],
            data: {},
          },
        ],
      },
    ],
  }),
});

const convertStorybookArgsToComponentProps = (args: CustomArgs) =>
  ({
    firstTitle: args.firstTitleText
      ? {
          text: args.firstTitleRichText
            ? { raw: JSON.stringify(args.firstTitleRichText) }
            : stringToSimpleRichText(args.firstTitleText),
          size: args.firstTitleSize,
          withBackground: args.firstTitleWithBackground,
          effect: {
            tiltDegrees: args.firstTitleTiltDegrees,
            dropShadow: args.firstTitleDropShadow,
          },
          colorOverrides: {
            background: args.firstTextColorOverrideBackground,
            text: args.firstTextColorOverrideText,
            dropShadow: args.firstTextColorOverrideDropShadow,
          },
        }
      : undefined,
    secondTitle: args.secondTitleText
      ? {
          text: args.secondTitleRichText
            ? { raw: JSON.stringify(args.secondTitleRichText) }
            : stringToSimpleRichText(args.secondTitleText),
          size: args.secondTitleSize,
          withBackground: args.secondTitleWithBackground,
          effect: {
            tiltDegrees: args.secondTitleTiltDegrees,
            dropShadow: args.secondTitleDropShadow,
          },
          colorOverrides: {
            background: args.secondTextColorOverrideBackground,
            text: args.secondTextColorOverrideText,
            dropShadow: args.secondTextColorOverrideDropShadow,
          },
        }
      : undefined,
    colorOverrides: {
      background: args.backgroundColorOverride,
      pausePlayButtonBackground: args.pausePlayButtonBackgroundColorOverride,
      pausePlayButtonIcon: args.pausePlayButtonIconColorOverride,
      buttonBackground: args.buttonBackgroundColorOverride,
      buttonText: args.buttonTextColorOverride,
    },
    logo: args.logo
      ? {
          imageMobile: args.logo.imageMobile,
          imageDesktop: args.logo.imageDesktop,
          position: args.logoPosition,
        }
      : undefined,
  }) satisfies Pick<ComponentProps<typeof HeroBlock>, "firstTitle" | "secondTitle" | "colorOverrides" | "logo">;

