/**
 * Note on the test:
 *
 * The goal is to ensure that either the mobile or desktop element is visible while the other is hidden.
 * This should be achieved using CSS, not conditional rendering. Both elements must be present in the DOM.
 *
 * Conditional rendering on the server could cause the desktop element to flicker in after the first paint, which we want to avoid.
 * Therefore, we use CSS to hide one of the elements to prevent any flickering.
 *
 * We also assert that the elements are different by comparing a unique string about the element, like the src-attribute on an image.
 * This is so we don't accidentally render the same element twice.
 */
const expectDifferentElementsAndOneHidden = async (
  canvas: { getByTestId: (testId: string) => HTMLElement },
  mobileTestId: string,
  desktopTestId: string,
  /**Some way to get a string that uniquely identifies this element. E.g. a src-attribute on an image.  */
  getUniqueStringAboutElement: (element: HTMLElement) => string | undefined,
) => {
  //Wait for 1 seconds to make sure the elements and assets have loaded
  await new Promise((resolve) => setTimeout(resolve, 1000));

  const mobileDiv = canvas.getByTestId(mobileTestId);
  const desktopDiv = canvas.getByTestId(desktopTestId);

  const mobileString = getUniqueStringAboutElement(mobileDiv);
  const desktopString = getUniqueStringAboutElement(desktopDiv);

  const isMobileHidden = window.getComputedStyle(mobileDiv).display === "none";
  const isDesktopHidden = window.getComputedStyle(desktopDiv).display === "none";

  //Se note above for explanation about the test
  expect(isMobileHidden).not.toBe(isDesktopHidden);
  expect(mobileString).not.toBe(desktopString);
};
